#!/usr/bin/env bash
#
# Install a WordPress test environment matched to a given WordPress version.
#
# Modelled on the canonical script generated by `wp scaffold plugin-tests`.
# Downloads:
#   1. The WordPress source for the target version (or trunk).
#   2. The matching version of the WordPress phpunit test scaffolding from
#      develop.svn.wordpress.org (this is the same set of files the
#      `wp-phpunit/wp-phpunit` package mirrors to packagist, but pinned to the
#      WordPress version under test rather than to a fixed composer constraint).
#
# Usage:
#   bin/install-wp-tests.sh <db-name> <db-user> <db-pass> [db-host] [wp-version]
#
# Example:
#   bin/install-wp-tests.sh wordpress_test root '' 127.0.0.1 6.5
#
# Expects the env vars WP_TESTS_DIR / WP_CORE_DIR to optionally override the
# install locations.
#
# Plugin-agnostic: this script installs WordPress + the test scaffold + an
# empty DB. It does NOT install FluentCart — the integration suite is
# deliberately hermetic and exercises only the parts of the plugin that don't
# require FluentCart's classes/tables to be present.

set -euo pipefail

DB_NAME="${1:-wordpress_test}"
DB_USER="${2:-root}"
DB_PASS="${3:-}"
DB_HOST="${4:-127.0.0.1}"
WP_VERSION="${5:-latest}"

WP_TESTS_DIR="${WP_TESTS_DIR:-/tmp/wordpress-tests-lib}"
WP_CORE_DIR="${WP_CORE_DIR:-/tmp/wordpress}"

download() {
	local url="$1" dest="$2"
	if command -v curl >/dev/null 2>&1; then
		curl -sSL "$url" -o "$dest"
	else
		wget -q "$url" -O "$dest"
	fi
}

# --- Resolve the WP_VERSION + WP_TESTS_TAG ----------------------------------

case "$WP_VERSION" in
	trunk|nightly)
		WP_TESTS_TAG="trunk"
		WP_DOWNLOAD_URL="https://wordpress.org/nightly-builds/wordpress-latest.zip"
		WP_IS_NIGHTLY=1
		;;
	latest)
		WP_VERSION_RESOLVED=$(download https://api.wordpress.org/core/version-check/1.7/ - | \
			php -r 'echo json_decode(stream_get_contents(STDIN))->offers[0]->version;')
		WP_TESTS_TAG="tags/${WP_VERSION_RESOLVED}"
		WP_DOWNLOAD_URL="https://wordpress.org/wordpress-${WP_VERSION_RESOLVED}.tar.gz"
		WP_IS_NIGHTLY=0
		;;
	*)
		WP_TESTS_TAG="tags/${WP_VERSION}"
		WP_DOWNLOAD_URL="https://wordpress.org/wordpress-${WP_VERSION}.tar.gz"
		WP_IS_NIGHTLY=0
		;;
esac

echo "==> WordPress version: ${WP_VERSION}"
echo "==> Test scaffold tag: ${WP_TESTS_TAG}"

# --- WordPress core ---------------------------------------------------------

install_wp() {
	if [ -d "${WP_CORE_DIR}" ] && [ -f "${WP_CORE_DIR}/wp-load.php" ]; then
		echo "==> WordPress core already present at ${WP_CORE_DIR}, skipping download."
		return
	fi

	mkdir -p "${WP_CORE_DIR}"

	if [ "${WP_IS_NIGHTLY}" -eq 1 ]; then
		local zip="/tmp/wordpress-nightly.zip"
		local stage
		stage="$(mktemp -d /tmp/wp-nightly-stage.XXXXXX)"
		download "${WP_DOWNLOAD_URL}" "${zip}"
		unzip -q -o "${zip}" -d "${stage}"
		# The nightly zip ships a single top-level `wordpress/` directory.
		cp -R "${stage}/wordpress/." "${WP_CORE_DIR}/"
		rm -rf "${stage}"
	else
		local tar="/tmp/wordpress.tar.gz"
		download "${WP_DOWNLOAD_URL}" "${tar}"
		tar -xzf "${tar}" --strip-components=1 -C "${WP_CORE_DIR}"
	fi

	test -f "${WP_CORE_DIR}/wp-load.php"
	echo "==> Installed WordPress core at ${WP_CORE_DIR}"
}

# --- Test scaffold (matched to WP version) ----------------------------------

install_test_suite() {
	if [ -d "${WP_TESTS_DIR}" ] && [ -d "${WP_TESTS_DIR}/includes" ]; then
		echo "==> Test scaffold already present at ${WP_TESTS_DIR}, skipping download."
		return
	fi

	# Pull the test scaffold from the WordPress develop SVN. This is the
	# authoritative source — wp-phpunit on packagist mirrors it, but we want
	# the exact files for the version we're testing against.
	mkdir -p "${WP_TESTS_DIR}/includes" "${WP_TESTS_DIR}/data"

	if ! command -v svn >/dev/null 2>&1; then
		echo "ERROR: svn is required to install the WP test scaffold." >&2
		exit 1
	fi

	svn export --quiet --force "https://develop.svn.wordpress.org/${WP_TESTS_TAG}/tests/phpunit/includes/" "${WP_TESTS_DIR}/includes"
	svn export --quiet --force "https://develop.svn.wordpress.org/${WP_TESTS_TAG}/tests/phpunit/data/"     "${WP_TESTS_DIR}/data"

	echo "==> Installed test scaffold at ${WP_TESTS_DIR}"
}

# --- wp-tests-config.php ----------------------------------------------------

install_config() {
	local config="${WP_TESTS_DIR}/wp-tests-config.php"

	if [ -f "${config}" ]; then
		echo "==> wp-tests-config.php already present, skipping."
		return
	fi

	cat > "${config}" <<-PHP
		<?php
		define( 'ABSPATH', '${WP_CORE_DIR}/' );
		define( 'WP_DEFAULT_THEME', 'default' );

		define( 'DB_NAME',     '${DB_NAME}' );
		define( 'DB_USER',     '${DB_USER}' );
		define( 'DB_PASSWORD', '${DB_PASS}' );
		define( 'DB_HOST',     '${DB_HOST}' );
		define( 'DB_CHARSET',  'utf8' );
		define( 'DB_COLLATE',  '' );

		\$table_prefix = 'wptests_';

		define( 'WP_TESTS_DOMAIN', 'example.org' );
		define( 'WP_TESTS_EMAIL',  'admin@example.org' );
		define( 'WP_TESTS_TITLE',  'Vatly for FluentCart Test Suite' );
		define( 'WP_PHP_BINARY',   'php' );
		define( 'WPLANG',          '' );

		define( 'WP_DEBUG', true );
		define( 'WP_DEBUG_DISPLAY', false );
		define( 'WP_DEBUG_LOG', false );
	PHP

	echo "==> Wrote ${config}"
}

# --- DB --------------------------------------------------------------------

install_db() {
	if [ -z "$(command -v mysqladmin)" ]; then
		echo "==> mysqladmin not on PATH; assuming DB '${DB_NAME}' already exists."
		return
	fi

	local host_args=("-h" "${DB_HOST%%:*}")
	if [[ "${DB_HOST}" == *:* ]]; then
		host_args+=("-P" "${DB_HOST##*:}")
	fi

	local pass_args=()
	if [ -n "${DB_PASS}" ]; then
		pass_args+=("-p${DB_PASS}")
	fi

	mysqladmin "${host_args[@]}" -u "${DB_USER}" "${pass_args[@]}" --force drop "${DB_NAME}" 2>/dev/null || true
	mysqladmin "${host_args[@]}" -u "${DB_USER}" "${pass_args[@]}" create "${DB_NAME}"
	echo "==> Created database ${DB_NAME}"
}

install_wp
install_test_suite
install_config
install_db

echo
echo "==> Done."
echo "    WP_CORE_DIR  = ${WP_CORE_DIR}"
echo "    WP_TESTS_DIR = ${WP_TESTS_DIR}"
